package com.fitbite.controller; import com.fitbite.dto.*; import com.fitbite.dto.AuthDtos.*; import com.fitbite.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController{private final AuthService service;public AuthController(AuthService service){this.service=service;}@PostMapping("/register") public ResponseEntity<ApiResponse<AuthResponse>> register(@Valid @RequestBody RegisterRequest r){return ResponseEntity.status(201).body(ApiResponse.ok("Registration successful",service.register(r)));}@PostMapping("/login") public ApiResponse<AuthResponse> login(@Valid @RequestBody LoginRequest r){return ApiResponse.ok("Login successful",service.login(r));}}
